18	async function route(req, res) {
19	  if (req.method === "POST" && req.url === "/users") {
20	    const body = await readJson(req);
21	    const errors = validateBody({ name: "string", email: "string" }, body);
22	    if (errors.length) return send(res, 400, { errors });
23	    users.set(body.email, body);
24	    return send(res, 201, body);
25	  }
26	  if (req.method === "PATCH" && req.url.startsWith("/users/")) {
27	    const body = await readJson(req);
28	    const errors = validateBody({ name: "string" }, body);
29	    if (errors.length) return send(res, 400, { errors });
30	    const email = decodeURIComponent(req.url.slice("/users/".length));
31	    users.set(email, { ...users.get(email), ...body });
32	    return send(res, 200, users.get(email));
33	  }
34	  if (req.method === "POST" && req.url === "/orders") {
35	    const body = await readJson(req);
36	    // TODO: check that the user exists
37	    if (typeof body.sku !== "string" || !(body.quantity > 0)) return send(res, 400, { error: "invalid order" });
38	    orders.push(body);
