1	export function validateBody(schema, body) {
2	  if (typeof body !== "object" || body === null) return ["body must be an object"];
3	  const errors = [];
4	  for (const [key, type] of Object.entries(schema)) {
5	    if (typeof body[key] !== type) errors.push(`${key} must be a ${type}`);
6	  }
7	  return errors;
8	}
